CREATE TABLE IF NOT EXISTS `PREFIX_cm_wilayas` (`id` INT UNSIGNED NOT NULL, `name` VARCHAR(100) NOT NULL, `is_deliverable` TINYINT(1) NOT NULL DEFAULT 1, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `PREFIX_cm_communes` (`id` INT UNSIGNED NOT NULL, `wilaya_id` INT UNSIGNED NOT NULL, `name` VARCHAR(150) NOT NULL, `has_stop_desk` TINYINT(1) NOT NULL DEFAULT 0, `is_deliverable` TINYINT(1) NOT NULL DEFAULT 1, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_wilaya_id` (`wilaya_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `PREFIX_cm_centers` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `carrier_code` VARCHAR(50) NOT NULL, `center_id` INT UNSIGNED NOT NULL, `commune_id` INT UNSIGNED NOT NULL, `wilaya_id` INT UNSIGNED NOT NULL, `name` VARCHAR(200) NOT NULL, `address` VARCHAR(500) DEFAULT NULL, `commune_name` VARCHAR(150) DEFAULT NULL, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_carrier_center` (`carrier_code`, `center_id`), KEY `idx_commune_id` (`commune_id`), KEY `idx_carrier_commune` (`carrier_code`, `commune_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
